questionvariables.text:
/* Données des gaz disponibles */
/* Format: [nom, [raies en nm]] */
gaz_data: [
  ["de l'Hydrogène", [410.2, 434.0, 486.1, 656.3]],
  ["de l'Hélium", [447.1, 471.3, 501.6, 587.6, 667.8]],
  ["du Sodium", [589.0, 589.6]],
  ["du Mercure", [404.7, 435.8, 546.1, 576.9]],
  ["du Néon", [585.2, 640.2, 650.7, 703.2]],
  ["de l'Argon", [696.5, 706.7, 763.5, 811.5]],
  ["de l'Oxygène", [436.8, 533.0, 615.8, 777.4]],
  ["de l'Azote", [399.5, 463.1, 500.5, 567.8, 648.2]],
  ["du Lithium", [610.3, 670.8]],
  ["du Cadmium", [467.8, 480.0, 508.6, 643.8]],
  ["du Krypton", [557.0, 587.1, 760.2]],
  ["du Xénon", [462.7, 467.1]]
];

/* Tirage aléatoire d'un gaz parmi plusieurs */
taille:length(gaz_data);
gaz_numero: rand(taille) + 1;

gaz_nom: gaz_data[gaz_numero][1];
gaz_raies: gaz_data[gaz_numero][2];


/* Données de calibration connues par l'élève */
/* Raie à 400 nm -> position 2.5 cm, raie à 700 nm -> position 17.5 cm */
lambda_ref1: 400;
pos_ref1: 2.5;
lambda_ref2: 700;
pos_ref2: 17.5;

/* Coefficient de proportionnalité (nm/cm) */
coef_prop: (lambda_ref2 - lambda_ref1)/(pos_ref2 - pos_ref1);

/* Conversion des raies en positions (cm) */
gaz_positions: maplist(lambda([x], pos_ref1 + (x - lambda_ref1)/coef_prop), gaz_raies);

/* Nombre de raies à identifier */
nb_raies: length(gaz_raies);

/* 2. Tirer 2 indices distincts entre 1 et nb_raies */
/* rand_selection(liste, n) choisit n éléments au hasard sans répétition */
indices_choisis: rand_selection(makelist(i, i, 1, nb_raies), 2);

/* 3. Trier les indices pour identifier Raie 1 et Raie 2 (optionnel mais conseillé) */
indices_trie: sort(indices_choisis);

/* 4. Récupérer les valeurs correspondantes pour tes réponses attendues */
index_raie1: indices_trie[1];
index_raie2: indices_trie[2];

val_raie1: gaz_raies[index_raie1];
val_raie2: gaz_raies[index_raie2];
ta1:val_raie1 * nm;
ta2:val_raie2* nm;

d1:float(round(100*(val_raie1-350.4)/20))/100 ;
d2:float(round(100*(val_raie2-350.4)/20))/100 ;
d11:d1-2.48;
d22:d2-2.48;
delta1:d11*20;
delta2:d22*20;
